<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Portal de Eventos</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <div id="app">
    <!-- Tela de Login/Registro -->
    <div id="auth-screen" class="screen active">
      <div class="auth-container">
        <div class="auth-header">
          <h1>🎉 Portal de Eventos</h1>
          <p>Gerencie suas inscrições em eventos</p>
        </div>

        <div class="auth-tabs">
          <button class="tab-btn active" data-tab="login">Entrar</button>
          <button class="tab-btn" data-tab="register">Criar Conta</button>
        </div>

        <!-- Formulário de Login -->
        <form id="login-form" class="auth-form active">
          <div class="form-group">
            <label>Email</label>
            <input type="email" id="login-email" required>
          </div>

          <div class="form-group">
            <label>Senha</label>
            <input type="password" id="login-password" required>
          </div>

          <button type="submit" class="btn btn-primary">Entrar</button>

          <div class="auth-help">
            <p><strong>Contas de teste:</strong></p>
            <p>Organizador: organizador@eventos.com / organizador123</p>
            <p>Participante: participante@eventos.com / participante123</p>
          </div>
        </form>

        <!-- Formulário de Registro -->
        <form id="register-form" class="auth-form">
          <div class="form-group">
            <label>Nome Completo</label>
            <input type="text" id="register-name" required>
          </div>

          <div class="form-group">
            <label>Email</label>
            <input type="email" id="register-email" required>
          </div>

          <div class="form-group">
            <label>Senha</label>
            <input type="password" id="register-password" required minlength="6">
          </div>

          <div class="form-group">
            <label>Tipo de Usuário</label>
            <select id="register-role" required>
              <option value="participante">Participante</option>
              <option value="organizador">Organizador</option>
            </select>
          </div>

          <button type="submit" class="btn btn-primary">Criar Conta</button>
        </form>
      </div>
    </div>

    <!-- Tela Principal -->
    <div id="main-screen" class="screen">
      <nav class="navbar">
        <div class="nav-content">
          <div class="nav-brand">🎉 Portal de Eventos</div>
          <div class="nav-user">
            <span id="user-name"></span>
            <button id="logout-btn" class="btn btn-secondary">Sair</button>
          </div>
        </div>
      </nav>

      <div class="main-content">
        <div class="sidebar">
          <button class="menu-item active" data-view="events">📅 Eventos Disponíveis</button>
          <button class="menu-item" data-view="my-registrations">✅ Minhas Inscrições</button>
          <button class="menu-item organizador-only" data-view="create-event">➕ Criar Evento</button>
          <button class="menu-item organizador-only" data-view="manage-events">⚙️ Gerenciar Eventos</button>
          <button class="menu-item organizador-only" data-view="all-registrations">👥 Todas as Inscrições</button>
        </div>

        <div class="content-area">
          <!-- View: Eventos Disponíveis -->
          <div id="events-view" class="view active">
            <h2>Eventos Disponíveis</h2>
            <div id="events-list" class="events-grid"></div>
          </div>

          <!-- View: Minhas Inscrições -->
          <div id="my-registrations-view" class="view">
            <h2>Minhas Inscrições</h2>
            <div id="my-registrations-list" class="registrations-list"></div>
          </div>

          <!-- View: Criar Evento -->
          <div id="create-event-view" class="view">
            <h2>Criar Novo Evento</h2>
            <form id="create-event-form" class="event-form">
              <div class="form-group">
                <label>Título do Evento</label>
                <input type="text" id="event-title" required>
              </div>

              <div class="form-group">
                <label>Descrição</label>
                <textarea id="event-description" rows="4" required></textarea>
              </div>

              <div class="form-row">
                <div class="form-group">
                  <label>Data e Hora</label>
                  <input type="datetime-local" id="event-date" required>
                </div>

                <div class="form-group">
                  <label>Vagas Máximas</label>
                  <input type="number" id="event-max" min="1" required>
                </div>
              </div>

              <div class="form-group">
                <label>Local</label>
                <input type="text" id="event-location" required>
              </div>

              <button type="submit" class="btn btn-primary">Criar Evento</button>
            </form>
          </div>

          <!-- View: Gerenciar Eventos -->
          <div id="manage-events-view" class="view">
            <h2>Gerenciar Meus Eventos</h2>
            <div id="manage-events-list" class="events-grid"></div>
          </div>

          <!-- View: Todas as Inscrições -->
          <div id="all-registrations-view" class="view">
            <h2>Todas as Inscrições</h2>
            <div id="all-registrations-list" class="registrations-list"></div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Modal de Edição de Evento -->
  <div id="edit-modal" class="modal">
    <div class="modal-content">
      <div class="modal-header">
        <h3>Editar Evento</h3>
        <button class="modal-close">&times;</button>
      </div>
      <form id="edit-event-form">
        <input type="hidden" id="edit-event-id">

        <div class="form-group">
          <label>Título do Evento</label>
          <input type="text" id="edit-event-title" required>
        </div>

        <div class="form-group">
          <label>Descrição</label>
          <textarea id="edit-event-description" rows="4" required></textarea>
        </div>

        <div class="form-row">
          <div class="form-group">
            <label>Data e Hora</label>
            <input type="datetime-local" id="edit-event-date" required>
          </div>

          <div class="form-group">
            <label>Vagas Máximas</label>
            <input type="number" id="edit-event-max" min="1" required>
          </div>
        </div>

        <div class="form-group">
          <label>Local</label>
          <input type="text" id="edit-event-location" required>
        </div>

        <div class="modal-actions">
          <button type="button" class="btn btn-secondary modal-close">Cancelar</button>
          <button type="submit" class="btn btn-primary">Salvar Alterações</button>
        </div>
      </form>
    </div>
  </div>

  <!-- Toast de Notificação -->
  <div id="toast" class="toast"></div>

  <script src="app.js"></script>
</body>
</html>

